      "title": "港理工发布《全球高等教育变革报告：百所顶尖高校人工智能创新驱动研究》：覆盖六大洲100所顶尖高校AI落地实践",
      "content": "2026全球智慧教育大会期间，香港理工大学教育研究与技术中心主任胡祥恩代表团队发布《全球高等教育变革报告：百所顶尖高校人工智能创新驱动研究》。报告提供英语、法语、西班牙语、俄语、阿拉伯语、中文六种联合国官方语言版本，系统梳理2020-2026年全球六大洲100所顶尖高校的人工智能落地实践，区分不同区域差异化转型路径，为全球高校合规、包容、可持续开展智能化办学体系提供实证支撑。大会还会期陆续推出《全球数字学习身心健康常设观测站共建计划》《'数字时代学习乡村'倡议及全球案例征集》《智能时代，教师如何'升级'——国际视野下的数字素养框架、测评与培养》及'AI员工'平台等标志性成果，智慧教育'全球框架+本土案例'互鉴机制成型。来源：CERNET 2026-08-20"
