      "title": "西交利物浦大学2026级新生开学典礼：9000余名来自90国新生入校，首次发布'12345'育人体系",
      "content": "8月30日，西交利物浦大学2026级新生开学典礼在苏州奥林匹克体育中心举行，来自全球90个国家和地区的9000余名本硕博新生入学。学校首次发布'12345'育人体系：1个人本锚点（以人为本、成长为纲、素养为核），2条探索途径（学术深海与产业社会双路径），3大共生生态（温暖包容校园、全球化数智知识、全场景社会实践），4类协同教育模式（西浦1.0至4.0），5星育人模式。执行校长席酉民致辞强调，当AI重构产业逻辑、单一成功标准逐渐失效，大学要帮助学生'和时代的变化共舞、永远保持人的主体性'——善用AI解放重复劳动，将精力投入创意、思辨、协作与复杂问题解决等不可替代的核心能力，AI素养成为开学季新生教育新主线。来源：西交利物浦大学官网 2026-08-30"
