      "content": "8月30日新生报到首日，南宁学院智慧迎新体系通过'扫码报到+校院两级实时大数据'实现新生报到全流程数字化管理。其智慧校园门户披露：8月6日体系全面上线后，信息化处协同发展规划处、学工处、财务处等部门，支撑新生来校前信息采集、选宿舍-选床位、绿色通道办理、财务交费、到站登记到核验报到全程在线'一站式'办理，其中选宿舍-选床位服务为今年首次推出；截至8月29日（报到前一日），72%的新生已线上办结全部入学事项，报到日则从到站、报到、绿色通道、财务交费、生源地等多维度数据，在校、院、专业不同层级精准调度、精细化支撑管理。9月1日全国高校集中开学，智慧迎新系统首秀实战。来源：教育数字化知识图谱 2026-08-30"
