      "content": "教育部科学技术与信息化司日前发布2026年6月教育信息化和网络安全工作月报（8月25日刊发）：国家中小学智慧教育平台网页版单月浏览量1.32亿次、访客量2834万人，App浏览量4.805亿次，智慧教育门户浏览量1048万次，国家职业教育智慧教育平台浏览量315.9万次；教育App备案管理平台通过并公布1447家企业提供的3370个教育类App，316205所学校完成使用者备案、备案率95.68%、29个省超80%，累计受理投诉举报1552起；6月10日教育部办公厅印发《关于进一步加强教育系统网络安全等级保护工作的通知》，6月22日国务院印发《教育发展'十五五'规划》、教育部在成都上线国家智慧教育平台终身学习中心。月报为开学季数据治理与安全工作提供权威基线。来源：CERNET 2026-08-25"
