      "content": "8月27日，浙江大学-香港理工大学数智创新联合研究院揭牌仪式在浙大举行，浙大党委书记任少波、香港理工大学校长滕锦光出席并为联合研究院揭牌。任少波表示，自1997年以来两校在人才培养、学者互访、学术交流等领域开展卓有成效的合作。新研究院聚焦数智创新领域，将依托两校优势学科推进科研联合攻关、高层次人才联合培养与成果转化，是内地与港澳高校共建数智创新平台的又一落地案例，为湾区与长三角教育资源联动提供参照。来源：浙江大学新闻网 2026-08-27"
