      "tag": "高教·规划解读",
      "title": "上海大学党委书记吴坚勇署名文章：以高质量党建引领保障上海教育'十五五'规划落地见效",
      "content": "8月21日，上海大学党委书记吴坚勇在教育在线发表署名文章《以高质量党建引领保障上海教育'十五五'规划落地见效》。文章指出，'十五五'时期是上海加快建设教育强市、推动高等教育蓄势突破、系统跃升的关键阶段，《上海市教育发展'十五五'规划》明确到2030年推动上海新时代立德树人新格局构建形成。文章围绕四条主线展开：坚持政治引领、把牢办学治校正确方向，落实党委领导下的校长负责制；强化铸魂育人、构建大思政育人新格局，升级'一校一特色'中国系列课程、打造理实融合的高质量思政教学案例库；强化组织保障、开展'一校一策'综合改革、实施地方高校服务贡献能力跃升计划，上海大学构建'1+3+N'集成电路协同育人联盟；夯实队伍支撑、完善以质量、贡献、绩效为核心的教师分类评价体系，鼓励技术推广应用、成果转化实绩纳入职称评审指标。'党建+大思政+综合改革+教师评价'四线联动，为高校落实'十五五'规划提供了可借鉴的校本路径。来源：上海大学/教育在线 2026-08-21 https://news.eol.cn/yaowen/202608/t20260821_2766698.shtml"
