      "tag": "教育数字化·终身学习",
      "title": "广东锚定'人工智能融入教育全要素、全过程、全场景'：教育大数据中心汇聚60余个教育智能体与垂类大模型",
      "content": "广东省教育厅8月21日发文介绍，广东锚定'人工智能融入教育全要素、全过程、全场景'方向，推动AI与终身学习深度融合：加快教育大数据中心建设，汇聚共享教育智能体、垂类大模型60余个，教育应用场景示范案例4000余个，打造数据与业务融合的终身教育一体化平台基座；印发《广东省人工智能+教育行动方案(2026-2028年)》，建立省、市、县、校四级智慧教育平台服务体系；上线广东全民终身学习平台并接入'粤省事'等端口，构建'一网通学'终身学习资源超市，与国家智慧教育平台终身学习中心建立资源共享机制；探索'资历框架+学分银行+学习成果认证'三位一体制度，学分银行信息化平台入驻省政务云、三大系统数据互通；发布《广东终身教育资历框架等级标准》，助力粤港澳'一试三证'，累计完成跨境认证4000余人。'教育智能体+垂类大模型'进入省级基础设施化阶段，为职业院校终身教育与社会培训数字化提供了完整样板。来源：广东省教育厅/教育在线 2026-08-21 https://news.eol.cn/yaowen/202608/t20260821_2766692.shtml"
