      "content": "8月13日，教育对口支援西藏工作会议暨教育系统援藏干部人才座谈会在拉萨召开，教育部部长怀进鹏出席并讲话。会议总结'十四五'教育援藏成效，部署'十五五'时期以铸牢中华民族共同体意识为主线，聚焦精准援藏、系统援藏、长期援藏，加快补齐基础教育质量短板、适应人口变化优化教育资源布局，一体推进教育科技人才工作。在藏期间，怀进鹏还调研了林芝市职业技术学校、西藏农牧大学等院校。'职业教育创新转型'与教育数字化资源共享将成为下一阶段教育援藏的重要抓手，中高职对口援藏院校可据此规划数字化帮扶与专业共建方案。来源：教育部/教育在线 2026-08-17 https://news.eol.cn/yaowen/202608/t20260817_2765501.shtml"
