      "content": "8月8日，'教育强边：聚力与赋能'边疆教育高质量发展政策与规划专题研讨会在广西百色召开，汇聚全国百位专家学者。教育部民族教育发展中心副主任宁锐提出'AI与教育深度融合已不是选择题、而是必答题'；专家报告聚焦'国门学校'建设，提出实施'硬软用'三位一体数字引擎赋能跃升行动；刘益东研究员认为AI将驱动边疆教育跨越式发展、能力证书将替代学历证书。会上还发布了《广西边疆地区基础教育发展报告(2026)》。边疆与民族地区学校的智慧校园建设正从'补齐短板'转向'AI换道超车'叙事，数字资源共享与AI应用成为政策关注点。来源：教育在线 2026-08-15 https://news.eol.cn/yaowen/202608/t20260815_2765465.shtml"
