      "tag": "AI教育",
      "title": "黑龙江启动'1+13'人工智能教育教学研究中心建设，哈工大牵头覆盖理工农医文",
      "content": "近日，黑龙江省'1+13'人工智能教育教学研究中心启动建设：省教育厅支持哈尔滨工业大学牵头建设省级中心，支持哈尔滨工程大学、东北林业大学、东北农业大学、哈尔滨医科大学、哈尔滨理工大学等高校围绕船海核、生态、农业、医学、智能制造等领域成立分中心，覆盖理工农医文等学科门类。中心立足国家人工智能产教融合创新平台等基础，依托各校航天、海洋工程、能源开发、智慧农业、冰雪经济等特色学科，以'教育先行牵引产业升级'为核心，前瞻研究未来5—10年AI对产业变革与岗位重塑的影响，并聚焦未来学校、未来学习中心、未来教师、未来课堂等'四个未来'形态，推动AI深度赋能教、学、管、研、评全流程。'1+N'主中心+分中心协同模式，为地方高校布局'人工智能+'产教融合提供了可复制的组织范式。来源：黑龙江省教育厅/教育在线 2026-08-14 https://news.eol.cn/yaowen/202608/t20260814_2765256.shtml"
