      "content": "8月14日，江苏省政府印发《江苏高水平大学建设方案(2026-2030年)》(苏政发〔2026〕75号)。方案明确顺应人工智能推动教育变革新趋势，深入推进教育科技人才一体发展，聚力打造一流高水平大学集群：到2030年，1-2所高校进入世界一流大学前列、3-5所进入世界一流大学行列，新增高校及学科进入国家'双一流'建设序列，10所以上省属高校综合实力进入国内前列；聚力打造学科高峰，10个左右学科建成世界顶尖学科。任务聚焦培养数智时代复合型创新人才、面向集成电路/人工智能/遥感/纳米/低空等领域发展新兴交叉学科、建设产业学院与卓越工程师学院等，为地方高校'十五五'学科布局与人才培养改革提供了参照。来源：江苏省人民政府/教育在线 2026-08-14 https://news.eol.cn/yaowen/202608/t20260814_2765235.shtml"
