  "trends": "本周地方'十五五'教育规划进入密集发布期，重庆、广西接连公布蓝图，共同指向三个关键词：'分类发展'（研究型/应用型/技能型错位竞争）、'专业—产业映射'（学科专业群对接地方产业集群）、'AI 复合型人才培养'（微专业、双学位、AI 通识课）。与此同时，山东以省级纲要首次系统划定 AI 教学的人机协同边界——'工具可用、主体在人'。对职业院校信息中心与教务部门而言，'十五五'规划窗口期正从'建平台、上系统'转向'数据治理 + AI 应用场景落地'，建议趁暑假收尾阶段梳理本校数字化底座与 AI 教学场景清单，为新一轮规划申报与专项建设做好准备。",
