        "content": "8月9日，第二轮'双高计划'（'新双高'）申报距8月15日截止仅剩6天。综合此前报道，本轮计划数字化指标权重较首轮提升30%，申报院校须具备成熟的智慧校园基础设施、数据中台建设能力和AI教学应用场景。本周末是多数院校申报材料封板的最后窗口，数字化实证数据、AI教学应用案例与社会服务能力佐证需逐项核验。来源：综合整理自教育部官网及此前早报已引用来源 http://www.moe.gov.cn"
