        "content": "8月8日山东印发中小学AI通识教育指南（严禁AI代写作业、替代授课）后，行业周末讨论聚焦'AI使用边界'：与宁波全学段AI通识方案、上海AI素养评价框架呼应，地方层面已形成'课程—评价—使用边界'的制度拼图。对职业院校的启示：秋季学期AI助教、智能批改等应用落地前，应同步制定师生使用规范与内容审核机制，把'人的主体地位'落到具体制度。来源：芥末堆 2026-08-08 https://www.jiemodui.com/N/139501.html"
