        "content": "8月6日CERNET刊发江苏省教育厅文章：江苏建立'省级统筹—区域推进—学校实施'三级工作机制，全省确立13个实验区、269所项目实验校、72所样本监测校；发布省域《STEM课程指导纲要》、开发覆盖全学段28册标准化课程资源；连续七年举办全省STEM教育大会，与联合国教科文组织国际STEM教育研究所（上海）围绕'大中小学贯通培养''AI赋能教学'等议题开展合作，无锡市在智慧教育云平台开设科学教育专属板块投放普惠性科教资源包。来源：CERNET 2026-08-06 https://www.edu.cn/info/focus/df/202608/t20260806_2763288.shtml"
