    "trends": "周四趋势观察：一是高校智能体建设进入'有组织研发'新阶段，南开大学NK-GeniOS平台在1.6万用户、1.5万个智能体的底座之上，明确从'大众创新'转向'有组织研发'、以'揭榜挂帅'对接真实业务需求，并把数据治理作为前提由校长挂帅高位推动，'数据质量决定智能体上限'正在成为共识；二是校院两级协同成为智慧校园深水区议题，华中科技大学依托统一基础数据平台打通实验室预约排课、设备维护、教学数据汇聚、移动服务四个维度，'不另起炉灶、依托统一底座'的建设思路对院校更有借鉴价值；三是科学教育区域范式加速成型，江苏省以'三级推进、全域覆盖'构建科技教育实施体系，13个实验区、269所实验校并连续七年办STEM教育大会，AI赋能教学、智慧教育云平台科学板块等信息化支撑成为标配；四是职教专业动态调整常态化，贵州省首次以清单形式明确本科急需与高职紧缺专业，职业院校秋季专业建设会议应把对照清单作为核心议题；五是就业服务场景创新加速，广西把双选会搬进高铁站，就业服务从校园走向交通枢纽等流量场景。对中高职院校的整体判断：距'新双高'申报截止（8月15日）仅剩9天，实证材料封板进入读秒阶段；对照贵州等省专业清单开展专业布局自评、借鉴南开数据治理与华科校院贯通思路完善'十五五'规划正文，是本周可以并行推进的两项务实工作。",
