        "content": "8月4日CERNET刊发详细报道：7月27日至28日教育部举办高校党政主要负责同志专题研讨班，教育部党组书记、部长怀进鹏作'学习贯彻习近平党建思想 加快教育强国建设步伐'主题报告。研讨班聚焦教育强国建设全局性、战略性议题，高校'十五五'规划编制与AI赋能教育教学改革是讨论重点。各院校'十五五'信息化规划的定稿节奏预计将在8月明显加快。来源：CERNET 2026-08-04 https://www.edu.cn/info/focus/li_lun_yj/202607/t20260731_2761802.shtml"
