    "title": "每日早报 | 教育信息化·智慧校园·AI教育",
    "summary": "周五观察：雄安新区IPv6单栈部署行动正式启动、人工智能大模型IPv6能力提升专项行动同步启动；APEC人工智能高级别论坛成都发声、Internet2报告提示AI竞争不止于算力；东南大学'善问'行政制度助手、芥末堆'AI重构教培'深度文章同日登场。",
    "items": [
      {
        "tag": "网络基座",
        "title": "雄安新区IPv6单栈部署行动启动，2030年新建片区全面实现单栈运行",
        "content": "7月31日河北日报报道，7月28日第五届中国IPv6创新发展大会在雄安举办，大会期间雄安新区IPv6单栈部署行动正式启动，将从夯基础、广赋能、强攻关、育生态四个维度推进，到2030年新建片区全面实现IPv6单栈规模化运行。大会同步启动人工智能大模型IPv6能力提升专项行动、发布《中国IPv6发展报告（2026）》。截至2025年底，我国移动网络和固定网络IPv6流量占比分别达70.85%和32.38%，IPv6网络、用户和流量规模居世界第一。来源：河北日报/CERNET 2026-07-31 https://www.edu.cn/info/focus/df/202607/t20260730_2761354.shtml"
      },
      {
        "tag": "AI治理",
        "title": "APEC人工智能高级别论坛在成都举行，发表亚太AI治理与合作文件",
        "content": "7月31日CERNET报道，7月24日亚太经合组织（APEC）人工智能高级别论坛在成都举行，论坛发表关于促进亚太地区人工智能治理与合作的文件。AI治理正从单边监管走向区域多边协调，教育领域AI应用的伦理框架、数据跨境流动与未成年人保护预计将成为后续亚太合作议题中的重点方向。来源：CERNET 2026-07-31 https://www.edu.cn/focus/rd_xin_wen/202607/t20260730_2761358.shtml"
      },
      {
        "tag": "前沿",
        "title": "Internet2报告：AI竞争的关键变量不止于大模型、GPU与算力中心",
        "content": "7月31日CERNET报道，美国科研教育网络组织Internet2近期发布研究报告提示，谈到AI竞争，人们首先想到的通常是大模型、GPU和算力中心，但科研教育网络、数据流通与协同生态同样是关键变量。对高校而言，除算力投入外，网络基座、数据资产与跨机构协同能力同样决定AI竞争力。来源：CERNET 2026-07-31 https://www.edu.cn/focus/rd_xin_wen/202607/t20260730_2761568.shtml"
      },
      {
        "tag": "智慧校园",
        "title": "东南大学推出'善问'行政制度助手，AI深入行政管理场景",
        "content": "7月31日CERNET报道，2026年上半年东南大学聚焦校园网络、行政事务、人才培养、国际交流、作风建设等重点领域，推出'善问'行政制度助手。高校AI应用正从教学科研向行政管理纵深渗透，'制度问答+流程导办'类智能体成为智慧校园新的标配场景。来源：CERNET 2026-07-31 https://www.edu.cn/xy/202607/t20260731_2761693.shtml"
      },
      {
        "tag": "深度",
        "title": "芥末堆刊文'AI重构教培：一场比双减影响更彻底的产业革命'",
        "content": "7月31日芥末堆刊发深度文章指出，AI对教培行业的重构将比双减影响更彻底：内容生产、教学交付到个性化服务链条全面再造，认知与战略选择决定生死。对学校端而言，AI重构的不只是培训机构，也包括校内教与学的组织方式，'教师角色再定义'成为学校与机构共同面对的课题。来源：芥末堆 2026-07-31 https://www.jiemodui.com/N/139492.html"
      }
    ],
    "trends": "周五趋势观察：一是IPv6单栈部署从倡议走向行动，雄安新区率先启动单栈部署行动并同步启动人工智能大模型IPv6能力提升专项行动，叠加此前14家单位倡议书，'IPv6单栈+AI'成为下一代校园网规划绕不开的技术主线；二是AI治理与AI竞争认知双线升级，APEC论坛发表亚太AI治理合作文件、Internet2报告把科研教育网络与数据流通纳入AI竞争关键变量，提示高校AI投入需要算力、网络基座、数据治理协同推进；三是高校AI应用继续向行政场景渗透，东南大学'善问'行政制度助手覆盖校园网络、行政事务等五大领域，'制度问答+流程导办'类智能体进入智慧校园标配清单；四是行业对AI与教培关系的反思进入深水区，芥末堆'AI重构教培'提出AI影响比双减更彻底，学校端同样需要重新思考教与学的组织方式。对中高职院校的整体判断：距'新双高'申报截止（8月15日）仅剩15天，实证材料进入封板阶段；建议同步启动校园网IPv6单栈演进与AI流量容量的规划预研，为'十五五'网络基座规划储备依据。",
    "sources": "综合整理自中国教育和科研计算机网CERNET（雄安新区IPv6单栈部署行动启动 2026-07-31 https://www.edu.cn/info/focus/df/202607/t20260730_2761354.shtml；APEC人工智能高级别论坛在成都举行 2026-07-31 https://www.edu.cn/focus/rd_xin_wen/202607/t20260730_2761358.shtml；Internet2关于AI竞争的研究报告 2026-07-31 https://www.edu.cn/focus/rd_xin_wen/202607/t20260730_2761568.shtml；东南大学'善问'行政制度助手 2026-07-31 https://www.edu.cn/xy/202607/t20260731_2761693.shtml）、芥末堆（AI重构教培深度文章 2026-07-31 https://www.jiemodui.com/N/139492.html）。说明：今日web_search提供方余额不足（429），改用web_fetch直抓权威来源整理；芥末堆文章详情页为JS渲染无法抓取正文，内容基于列表页摘要整理，详情以原链接为准。"
