        "tag": "科学教育",
        "title": "唐山市第二届中小学科学运动会开赛，'做中学用中学创中学'",
        "content": "8月4日中国教育新闻网报道，河北省唐山市第二届中小学科学运动会火热开赛，以'好奇心想象力探求欲 做中学用中学创中学'为主题，由唐山市教育局主办。在教育部首批135个科技教育实验区公示后，区域层面的科学教育赛事活动明显增多，'以赛促教'成为科学教育规模化推进的常用抓手，赛事平台、实验装备与过程性评价工具存在配套采购空间。来源：中国教育新闻网 2026-08-04 http://www.jyb.cn/rmtzcg/xwy/wzxw/"
